"""Filling a .docx template: the document side.

Word happily splits ``{{ placeholder }}`` across several runs as you type, so
the runs are stitched back together first; then row, cell and paragraph control
tags (``{%tr for ... %}``) are relocated outside the element they sit in, so
the markup itself never reaches the page.  Rendering the resulting XML is the
job of engine.py.
"""
from __future__ import annotations

import io
import re
from xml.etree import ElementTree as ET

from ..oxml import local, package as opc, qn, Package
from .engine import render_string

TAG_RE = re.compile(r'\{[{%].*?[%}]\}', re.S)
CONTROL_RE = re.compile(r'\{%\s*(tr|tc|p|r)\s+(.*?)\s*%\}', re.S)
JINJA_REGION_RE = re.compile(r'\{[{%].*?[%}]\}', re.S)
COMMENT_RE = re.compile(r'<!--JINJA:(.*?)-->', re.S)

OPENERS = ('for', 'if', 'while', 'macro', 'block', 'with', 'filter', 'call',
           'raw', 'trans')
CLOSERS = ('endfor', 'endif', 'endwhile', 'endmacro', 'endblock', 'endwith',
           'endfilter', 'endcall', 'endraw', 'endtrans', 'else', 'elif')

XML_DECL = b'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\r\n'

ANCESTOR_TAGS = {'tr': 'tr', 'tc': 'tc', 'p': 'p', 'r': 'r'}


def _unescape(text: str) -> str:
    return (text.replace('&lt;', '<').replace('&gt;', '>')
            .replace('&quot;', '"').replace('&#34;', '"')
            .replace('&apos;', "'").replace('&#39;', "'")
            .replace('&amp;', '&'))


class DocxTemplate:
    """Fill ``{{ placeholders }}`` in a .docx and hand back a new .docx."""

    def __init__(self, source):
        self.package = source if isinstance(source, Package) else Package(source)
        self.main = self.package.main_part

    # -- public ---------------------------------------------------------
    def parts(self):
        """Every part whose text can carry placeholders."""
        names = [self.main]
        for rel in self.package.rels(self.main).values():
            if rel.type in (opc.RT_HEADER, opc.RT_FOOTER, opc.RT_FOOTNOTES,
                            opc.RT_ENDNOTES):
                names.append(self.package.resolve(self.main, rel.target))
        return names

    def variables(self) -> set:
        """Placeholder names used in the document (best effort)."""
        found = set()
        for name in self.parts():
            root = self.package.xml(name)
            if root is None:
                continue
            for para in root.iter(qn('w:p')):
                text = _paragraph_text(para)
                for match in re.finditer(r'\{\{\s*([a-zA-Z_][\w.]*)', text):
                    found.add(match.group(1))
                for match in re.finditer(r'\{%\s*(?:tr|tc|p|r)?\s*for\s+\w+\s+in\s+'
                                         r'([a-zA-Z_][\w.]*)', text):
                    found.add(match.group(1))
        return found

    def render(self, context: dict, jinja: bool = True) -> bytes:
        """Return new .docx bytes with the context applied."""
        updates = {}
        for name in self.parts():
            raw = self.package.read(name)
            rendered = self._render_part(raw, context, jinja)
            if rendered is not None:
                updates[name] = rendered
        return self.package.replace(updates)

    def save(self, target, context: dict, jinja: bool = True):
        data = self.render(context, jinja)
        if hasattr(target, 'write'):
            target.write(data)
        else:
            with open(target, 'wb') as fh:
                fh.write(data)
        return target

    # -- internals ------------------------------------------------------
    def _render_part(self, raw: bytes, context: dict, jinja: bool):
        prefixes = _collect_prefixes(raw)
        for prefix, uri in prefixes.items():
            if prefix:
                ET.register_namespace(prefix, uri)
        root = ET.fromstring(raw)
        text = _serialize_all(root)
        if '{{' not in text and '{%' not in text:
            return None
        parents = {child: parent for parent in root.iter() for child in parent}
        for para in list(root.iter(qn('w:p'))):
            _merge_runs(para)
        for para in list(root.iter(qn('w:p'))):
            _relocate_controls(para, parents, root)
        xml = ET.tostring(root, encoding='unicode')
        xml = COMMENT_RE.sub(lambda m: _unescape(m.group(1)), xml)
        xml = JINJA_REGION_RE.sub(lambda m: _unescape(m.group(0)), xml)
        rendered = render_string(xml, context, jinja)
        return XML_DECL + rendered.encode('utf-8')


def _serialize_all(root) -> str:
    return ''.join(el.text or '' for el in root.iter(qn('w:t'))) + ''.join(
        (el.text or '') for el in root.iter(qn('w:instrText')))


def _collect_prefixes(raw: bytes) -> dict:
    out = {}
    try:
        for event, (prefix, uri) in ET.iterparse(io.BytesIO(raw), events=('start-ns',)):
            out[prefix] = uri
    except ET.ParseError:
        pass
    return out


def _paragraph_text(para) -> str:
    return ''.join(t.text or '' for t in para.iter(qn('w:t')))


def _merge_runs(para):
    """Pull a placeholder that Word split across runs back into one run."""
    runs = [r for r in para.iter(qn('w:r'))]
    entries = []
    offset = 0
    for run in runs:
        texts = [t for t in run.iter(qn('w:t'))]
        if not texts:
            continue
        joined = ''.join(t.text or '' for t in texts)
        entries.append({'run': run, 'texts': texts, 'start': offset,
                        'end': offset + len(joined), 'text': joined})
        offset += len(joined)
    if not entries:
        return
    full = ''.join(e['text'] for e in entries)
    if '{' not in full:
        return
    spans = [(m.start(), m.end()) for m in TAG_RE.finditer(full)]
    # also stitch unterminated openers so '{{' + 'name }}' survives
    for match in re.finditer(r'\{[{%]', full):
        start = match.start()
        if any(s <= start < e for s, e in spans):
            continue
        end = full.find('}', start)
        if end >= 0:
            spans.append((start, end + 1))
    spans.sort()
    for start, end in reversed(spans):
        covered = [i for i, e in enumerate(entries)
                   if e['start'] < end and e['end'] > start]
        if len(covered) < 2:
            continue
        first = entries[covered[0]]
        merged = ''.join(entries[i]['text'] for i in covered)
        first['texts'][0].text = merged
        first['texts'][0].set(qn('xml:space'), 'preserve')
        for extra in first['texts'][1:]:
            extra.text = ''
        for index in covered[1:]:
            entry = entries[index]
            for t in entry['texts']:
                t.text = ''
            entry['text'] = ''
        first['text'] = merged
        first['end'] = entries[covered[-1]]['end']


def _relocate_controls(para, parents, root):
    """Move ``{%tr ... %}``-style tags outside their row/cell/paragraph."""
    texts = [t for t in para.iter(qn('w:t'))]
    for t in texts:
        if not t.text or '{%' not in t.text:
            continue
        while True:
            match = CONTROL_RE.search(t.text or '')
            if match is None:
                break
            scope = match.group(1)
            statement = '{%% %s %%}' % match.group(2).strip()
            t.text = (t.text[:match.start()] + t.text[match.end():])
            target = _ancestor(para, parents, ANCESTOR_TAGS[scope])
            if target is None:
                target = para
            parent = parents.get(target)
            if parent is None:
                continue
            index = list(parent).index(target)
            keyword = match.group(2).strip().split(' ', 1)[0]
            comment = ET.Comment('JINJA:' + statement)
            if keyword in CLOSERS:
                parent.insert(index + 1, comment)
            else:
                parent.insert(index, comment)
            parents[comment] = parent


def _ancestor(el, parents, tag_local):
    current = el
    while current is not None:
        if local(current.tag) == tag_local:
            return current
        current = parents.get(current)
    return None


def render_docx(source, context: dict, jinja: bool = True) -> bytes:
    """Fill a template and return the resulting .docx as bytes."""
    return DocxTemplate(source).render(context or {}, jinja=jinja)
